def build_overpass_query(bbox: Dict[str, float]) -> str:
    """Construct Overpass QL query for safety-critical civic context features."""
    s, w, n, e = bbox["south"], bbox["west"], bbox["north"], bbox["east"]
    bbox_str = f"{s},{w},{n},{e}"

    query = f"""
    [out:json][timeout:30];
    (
      // Hospitals & Clinics (L = 1.00 within 200m)
      node["amenity"="hospital"]({bbox_str});
      way["amenity"="hospital"]({bbox_str});

      // Schools & Colleges (L = 1.00 within 200m)
      node["amenity"="school"]({bbox_str});
      way["amenity"="school"]({bbox_str});

      // Primary & Secondary Arterial Roads (L = 0.90 within 30m)
      way["highway"="primary"]({bbox_str});
      way["highway"="secondary"]({bbox_str});

      // Transit Hubs & Markets (L = 0.70 within 200m)
      node["amenity"="bus_station"]({bbox_str});
      node["railway"="station"]({bbox_str});
      node["amenity"="marketplace"]({bbox_str});
    );
    out center;
    """
    return query

